/* Refreshes hiscores, applies the entry mode, then queues menu command 1 (status 7) or 0x10 (after updating item records) and closes the save menu. */ s32 updateItemRecordsAndUnlocks(); void closeSaveMenu(); s32 getEntryStatus(); s32 setEntryMode(s32); void requestSceneChange(s8); void resetSlotsAndRefreshAll(); extern s8 gPendingMenuCommand; void commitEntryAndCloseSaveMenu(s32 entryMode) { s8 menuCommand; resetSlotsAndRefreshAll(); setEntryMode(entryMode); requestSceneChange(0x24); if (getEntryStatus() != 7) { updateItemRecordsAndUnlocks(); menuCommand = 0x10; } else { menuCommand = 1; } gPendingMenuCommand = menuCommand; closeSaveMenu(); }
